$ErrorActionPreference='Stop'; $Root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path; $Out=Join-Path $Root 'release/evidence/P1A/platforms/windows'; Remove-Item -Recurse -Force $Out -ErrorAction SilentlyContinue; New-Item -ItemType Directory -Force (Join-Path $Out 'artifacts') | Out-Null
foreach($name in 'KRISTIN_P1A_PACKAGE_SHA256','KRISTIN_P1A_RUNNER_ATTESTATION_PROVIDER','KRISTIN_P1A_EVIDENCE_TRUST','KRISTIN_P1A_EVIDENCE_SIGNER','KRISTIN_P1A_WINDOWS_SIGNING_CERT_THUMBPRINT','GITHUB_RUN_ID','GITHUB_RUN_ATTEMPT','GITHUB_JOB','GITHUB_SHA'){if(-not (Get-Item "env:$name" -ErrorAction SilentlyContinue).Value){throw "missing $name"}}
python (Join-Path $Root 'tool/p1a_behavioral_orchestrator.py') --project $Root --platform windows --service-binary (Join-Path $Root '.p1a-build-windows/Release/kristin_p1_authority_service_windows.exe') --connector (Join-Path $Root '.p1a-connector-windows/Release/kristin_p1a_connector_cli.exe') --worker-launcher (Join-Path $Root '.p1a-worker-windows/Release/kristin_p2_worker_launcher.exe') --installer (Join-Path $Root 'authority_service/install/windows/Install-KristinP1Authority.ps1') --uninstaller (Join-Path $Root 'authority_service/install/windows/uninstall.ps1') --output $Out
